import base64, json, os, sys
sys.path.insert(0, '/Users/kenneth/Projects/JusPrin/tests/mcp')
from urllib.parse import urlsplit
from probe import call
S = '/private/tmp/claude/claude-502/-Users-kenneth-Projects-JusPrin/473348c5-5f94-4e4d-9ad9-c7e9dd10b438/scratchpad/app'
d = sys.argv[1]
ep = urlsplit(json.load(open(f'{S}/{d}/jusprin/mcp.json'))['url'])
def tool(name, **args):
    r = call(ep, 'tools/call', {'name': name, 'arguments': args})
    return r
mode = sys.argv[2]
if mode == 'tools':
    r = call(ep, 'tools/list')
    for t in r['result']['tools']:
        if t['name'] in ('project_open', 'view_render', 'workspace_inspect', 'presets_list', 'printer_setup_preview', 'printer_setup', 'object_import_file'):
            print(t['name'], json.dumps(t['inputSchema'])[:900]); print()
elif mode == 'call':
    r = tool(sys.argv[3], **json.loads(sys.argv[4] if len(sys.argv) > 4 else '{}'))
    res = r.get('result', r)
    for c in res.get('content', []) if isinstance(res, dict) else []:
        if c.get('type') == 'image':
            out = sys.argv[5] if len(sys.argv) > 5 else f'{S}/render.png'
            open(out, 'wb').write(base64.b64decode(c['data'])); print('image', out, len(c['data']))
        else:
            print(c.get('text', c)[:6000])
    if isinstance(res, dict) and 'structuredContent' in res:
        print(json.dumps(res['structuredContent'])[:6000])
    if 'error' in r: print(r['error'])

