    const theme = p.theme ?? 'light';
    const variant = p.variant ?? 'all';
    if (variant === 'all') {
      return { theme, frameStyle: FRAME, tiles: BOARD.map((n) => ({ ...view({ ...PRESETS[n] }), label: LABELS[n], tileStyle: TILE })) };
