30	CatalogPaths default_catalog_paths()
31	{
32	    CatalogPaths paths;
33	#ifdef _WIN32
34	    paths.windows = true;
35	    const auto profile = env("USERPROFILE");
36	    paths.home = profile.empty() ? fs::current_path() : fs::u8path(profile);
37	    const auto appdata = env("APPDATA");
38	    paths.config_home = appdata.empty() ? paths.home : fs::u8path(appdata);
39	#elif defined(__APPLE__)
40	    const auto home = env("HOME");
41	    paths.home = home.empty() ? fs::current_path() : fs::u8path(home);
42	    paths.config_home = paths.home / "Library" / "Application Support";
43	#else
44	    const auto home = env("HOME");
45	    paths.home = home.empty() ? fs::current_path() : fs::u8path(home);
46	    const auto xdg = env("XDG_CONFIG_HOME");
47	    paths.config_home = xdg.empty() ? paths.home / ".config" : fs::u8path(xdg);
48	#endif
49	    return paths;
50	}
51	
52	std::string command_on_path(const std::string& command)
53	{
54	#ifdef _WIN32
55	    const std::string filename = command + ".exe";
56	    const std::string path = env("PATH");
57	    const char separator = ';';
58	#else
59	    const std::string filename = command;
60	    const std::string path = env("PATH");
61	    const char separator = ':';
62	#endif
63	    std::string directory;
64	    std::istringstream stream(path);
65	    while (std::getline(stream, directory, separator)) {
66	        if (directory.empty()) continue;
67	        const auto candidate = fs::u8path(directory) / filename;
68	        if (executable_file(candidate)) return candidate.u8string();
69	    }
70	#ifndef _WIN32
71	    const auto home = env("HOME");
72	    for (const auto& extra : {fs::u8path(home) / ".local" / "bin", fs::path("/opt/homebrew/bin"), fs::path("/usr/local/bin")}) {
73	        const auto candidate = extra / filename;
74	        if (executable_file(candidate)) return candidate.u8string();
75	    }
76	#endif
77	    return {};
78	}
